[Form]
public class GUPPriceDetail extends FormRun
{
    private GUPPriceDetailForm      priceDetailForm;
    private SalesParameters         salesParameters;
    private PurchParameters         purchParameters;
    private RecId                   activeRecId;
    private TAMRebatePriceHistory   tamRebatePriceHistory;
    private Common                  caller;

}

/// <summary>
///     Valdiates the buffer type and intializes the form.
/// </summary>
public void init()
{
    // Validate passed in record is of right type
    if (! element.args()
        || ! (element.args().dataset()    == tableNum(PurchLine)
              || element.args().dataset() == tableNum(SalesLine)
              || element.args().dataset() == tableNum(SalesQuotationLine)))
    {
        throw error(strFmt("@MCR35593",
                           element.name(),
                           tableStr(PurchLine),
                           tableStr(SalesLine),
                           tableStr(SalesQuotationLine)));
    }

    super();

    if (TAMRebateFeatureManagementVisibilityManager::isFeatureEnabled())
    {
        tamRebatePriceHistory = TAMRebatePriceHistory::newFromPriceHistoryTmp(tamRebatePriceHistoryTmp_ds.cursor(), this.args().dataset());
    }

    this.setControls();
}

/// <summary>
/// Shows or hides controls depending on the type of price history line.  Updates values
/// of price controls such as price, discount amount, discount percentage, and line amount.
/// Displays updated margin estimation calculations.
/// </summary>
/// <remarks>
/// Use the <c>MCRPriceHistoryForm</c> object to retrieve values.
/// </remarks>
public void setControls()
{
    MCRMarginAlert  mcrMarginAlert;
    RepShowZero     repShowZero;
    boolean         agreementIsVolumeBased;
    boolean         showRebates;
    RecId           currentRecId;

    caller = element.args().record();

    if (activeRecId != caller.RecId)
    {
        activeRecId = caller.RecId;

        priceDetailForm = GUPPriceDetailForm::construct(caller);

        delete_from mcrPriceHistory;
        mcrPriceHistory_ds.executeQuery();

        //Disable labels for summerized amounts in each tab
        TotalNetPriceChange.showLabel(NoYes::No);
        BasePrice.showLabel(NoYes::No);
        TotalDiscountAmount.showLabel(NoYes::No);

        // Set line information
        itemId.text(priceDetailForm.getItemId());
        itemName.text(InventTable::find(priceDetailForm.getItemId()).itemName());
        qty.realValue(priceDetailForm.getQty());
        unitId.text(priceDetailForm.getUnitId());
        priceUnit.realValue(priceDetailForm.getPriceUnit());
        currencyCode.text(priceDetailForm.getCurrencyCode());

        //Total net amount add to caption
        NetAmountTabPage.caption(strFmt('@GlobalUnifiedPricing:GUPPriceDetailPreviewLabelFormat', '@GlobalUnifiedPricing:GUPPriceDetailNetAmountTab', num2Str(priceDetailForm.getDiscPctExtendedAmount(), -1, 2, DecimalSeparator::Dot, ThousandSeparator::Comma)));

        //Total net price change
        TotalNetPriceChange.realValue(priceDetailForm.displayTotalMarginComponentPriceChange());

        //Total discount amount
        TotalDiscountAmount.realValue((priceDetailForm.getUnitPriceExtendedAmount() - priceDetailForm.getDiscAmountExtendedAmount()) * -1);
        //Currently, discount does not support UOM, therefore, set unitId for all records;
        DiscountUnitId.text(priceDetailForm.getUnitId());

        //Total charge amount
        TotalChargeAmount.realValue(priceDetailForm.getTotalEstimatedChargeAmount());

        //Rebates
        if (tamRebatePriceHistory)
        {
            boolean showCustRebates = priceDetailForm.showCustRebates();
            boolean rebatesManagementVisible = showCustRebates || priceDetailForm.showVendRebates();

            if (rebatesManagementVisible)
            {
                TabPageRebates.visible(NoYes::Yes);
                tamRebatePriceHistory.populateTable(caller);
                tamRebatePriceHistoryTmp_ds.executeQuery();
                tamRebateGrid_RebateGroup.label(showCustRebates ? "@RebatesAndDeductions:CustomerRebateGroup" : "@RebatesAndDeductions:VendorRebateGroup");
            }
        }
    }
}

/// <summary>
/// Performs the default link active behavior when calling record changes.
/// </summary>
/// <remarks>
/// The temporary table is filled by the <c>MCRPriceHistoryForm</c> class.
/// The link active functionality is disabled in all temporary datasources
/// and handled through the InventDimHeader datasource.  This allows the
/// <c>MCRPriceHistoryForm</c> class to be instantiated just once for all
/// the temporary datasources.
/// </remarks>
public void linkActive()
{
    // super();
}

public void executeQuery()
{
    if (priceDetailForm)
    {
        // Initialize the query from the form helper which fills the temp table based
        // on the line from which the form was opened (purchase, sales, or quotation).
        mcrPriceHistory_ds.query(priceDetailForm.queryPriceHistory(mcrPriceHistory, false));
    }
    super();
}

public void executeQuery()
{
    QueryBuildDataSource queryBuildDataSource;
    QueryBuildRange      queryBuildRange;

    if (priceDetailForm
        && isConfigurationkeyEnabled(configurationKeyNum(Retail)))
    {
        queryBuildDataSource = retailSalesQuotationDiscountLineView_ds.queryBuildDataSource();
        queryBuildRange = queryBuildDataSource.findRange(fieldNum(RetailSalesQuotationDiscountLineView, InventTransId));
        queryBuildRange.value(queryValue(priceDetailForm.getInventTransId()));

        super();
    }
}

public void init()
{
    QueryBuildDataSource queryBuildDataSource;

    super();

    if (isConfigurationkeyEnabled(configurationKeyNum(Retail)))
    {
        queryBuildDataSource = retailSalesQuotationDiscountLineView_ds.queryBuildDataSource();
        queryBuildDataSource.clearDynalinks();
        queryBuildDataSource.addRange(fieldNum(RetailSalesQuotationDiscountLineView, InventTransId));
    }
}

public void executeQuery()
{
    if (priceDetailForm)
    {
        GUPMarginComponentAdjustmentHistory_ds.queryBuildDataSource()
            .addRange(fieldNum(GUPMarginComponentAdjustmentHistory, InventTransId))
            .value(queryValue(priceDetailForm.getInventTransId()));
    }
    super();
}

public void executeQuery()
{
    if (priceDetailForm)
    {
        QueryBuildDataSource qbds = MarkupTrans_ds.queryBuildDataSource();
        qbds.addRange(fieldNum(MarkupTrans, TransTableId)).value(queryValue(tableNum(SalesLine)));
        qbds.addRange(fieldNum(MarkupTrans, TransRecId)).value(queryValue(caller.RecId));
    }
    super();
}

public void jumpRef()
{
    Args args = new Args();
    FormRun formRun;

    args.parmEnumType(enumNum(RetailDiscountOfferTypeBase));
    args.parmEnum(RetailDiscountOfferTypeBase::Promotion);
    args.parm(GUPMarginComponentAdjustmentHistory.MarginComponentAdjustment);
    formRun = new MenuFunction(menuitemDisplayStr(GUPMarginComponentPriceAdjustments), MenuItemType::Display).create(args);

    formRun.run();
    formRun.wait();
}

public void jumpRef()
{
    Args args = new Args();            
    FormRun formRun;

    if (RetailSalesQuotationDiscountLineView.DiscountOriginType == RetailDiscountOriginType::Periodic)
    {
        args.parmEnumType(enumNum(RetailDiscountOfferTypeBase));
        args.parmEnum(RetailPeriodicDiscount::findByOfferId(RetailSalesQuotationDiscountLineView.PeriodicDiscountOfferId).PeriodicDiscountType);
        args.parm(RetailSalesQuotationDiscountLineView.PeriodicDiscountOfferId);
        formRun = new MenuFunction(menuitemDisplayStr(RetailDiscountOffer), MenuItemType::Display).create(args);
    }

    if (RetailSalesQuotationDiscountLineView.DiscountOriginType == RetailDiscountOriginType::Tender)
    {
        args.parm(RetailSalesQuotationDiscountLineView.PeriodicDiscountOfferId);
        formRun = new MenuFunction(menuitemDisplayStr(RetailTenderDiscount), MenuItemType::Display).create(args);
    }

    formRun.run();
    formRun.wait();
}

public void jumpRef()
{
    MenuFunction    menuFunction = new MenuFunction(menuitemdisplaystr(GUPPriceComponentCode), MenuItemType::Display);
    Args args = new Args(formstr(GUPPriceComponentCode));

    GUPPriceComponentCode priceComponentCode = GUPPriceComponentCode::findByName(RetailPeriodicDiscount::findByOfferId(RetailSalesQuotationDiscountLineView.PeriodicDiscountOfferId).PriceComponentCodeName);

    args.record(priceComponentCode);
    args.lookupRecord(priceComponentCode);
    menuFunction.run(args);
}
